package com.orderflow.delivery.controller;import com.orderflow.delivery.correlation.DeliveryRequestAttributes;import com.orderflow.delivery.dto.*;import com.orderflow.delivery.service.*;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/deliveries")public class AdminDeliveryController{private final DeliveryAssignmentService assignment;private final DeliveryQueryService query;public AdminDeliveryController(DeliveryAssignmentService a,DeliveryQueryService q){assignment=a;query=q;}@PostMapping("/{id}/assign")public DeliveryResponse assign(@PathVariable UUID id,@Valid @RequestBody AssignDeliveryRequest b,HttpServletRequest r){assignment.manualAssign(id,b.deliveryAgentId(),(String)r.getAttribute(DeliveryRequestAttributes.CORRELATION_ID));return query.byId(id,new UUID(0,0),true,false);}@GetMapping("/{id}/history")public PageResponse<HistoryResponse> history(@PathVariable UUID id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return query.history(id,page,size);}}
